mapper.select:
select t.pf_id,t.pf_id pfId,t.open_id,t.open_id openId,t.owner_type_cd,t.owner_type_cd
ownerTypeCd,t.remark,t.status_cd,t.status_cd statusCd,t.pfq_id,t.pfq_id pfqId,t.room_id,t.room_id
roomId,t.room_name,t.room_name roomName,t.person_name,t.person_name personName,t.face_url,t.face_url
faceUrl,t.state,t.community_id,t.community_id communityId,t.person_tel,t.person_tel personTel
from person_face t
where 1 =1

    and t.pf_id= #{pfId}


    and t.open_id= #{openId}


    and t.owner_type_cd= #{ownerTypeCd}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.pfq_id= #{pfqId}


    and t.room_id= #{roomId}


    and t.room_name= #{roomName}


    and t.person_name= #{personName}


    and t.face_url= #{faceUrl}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.person_tel= #{personTel}

order by t.create_time desc

    limit #{page}, #{row}

